import math

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

solutions = []
limit_x = 99

for x in range(1, limit_x + 1):
    D = x*x + 1
    if is_power_of_two(D):
        solutions.append(x)
        print(f"x={x}, D={D}")

print(f"All x values such that x^2+1 is a power of 2 (x < 100): {solutions}")

def is_power_of_3(n):
    if n <= 0:
        return False
    while n % 3 == 0:
        n //= 3
    return n == 1

print("Checking 2^z + 1 for odd z in [3, 99] to see if it is a power of 3.")
solutions = []
for z in range(3, 100, 2):
    N = pow(2, z) + 1
    if is_power_of_3(N):
        # We find k such that N = 3^k
        k = 0
        temp_N = N
        while temp_N > 1:
            temp_N //= 3
            k += 1
        solutions.append((z, k))
        print(f"Found solution: z={z}, N={N} = 3^{k}")

print("\nTotal solutions found:", solutions)

import math

def is_power_of_three(n):
    if n <= 0:
        return False
    while n > 1:
        if n % 3 != 0:
            return False
        n //= 3
    return True

# Search for x such that x^2 - x + 1 is a power of 3, for 2 <= x <= 99
solutions_z3 = []
for x in range(2, 100):
    Q = x**2 - x + 1
    if is_power_of_three(Q):
        solutions_z3.append((x, Q))

print("Solutions for z=3 (Q is a power of 3):", solutions_z3)
